SQL_DOC.P_SQL:
SELECT A.REF_NO AS PLANT, A.QUOTATION_NO AS RE_NO, A.QUOTATION_SEQ AS RE_SEQ, A.REVISION, DECODE(B.BID_SUCCESS_FLAG,'Y','3494',B.AGENT) AS AGENT_CODE, DECODE(B.BID_SUCCESS_FLAG,'Y','코리아이플랫폼(주)',C.COM_NAME_LOC) AS AGENT_NAME, B.STATUS, A.BUYER_ITEM_NO, B.ATOB_UNIT_PRICE AS T_PRICE, DECODE(B.BID_SUCCESS_FLAG,'Y','1','0') AS IFDECIS, TO_CHAR(SYSDATE,'YYYYMMDD') AS IFDATE, TO_CHAR(SYSDATE,'HH24MISS') AS IFTIME FROM KEPRQDT A, KEPQTDT B, ICOMCMPY C, ICOMTRXL D WHERE D.DOC_NAME = 'QTHDDOWN' AND D.TARGET IN ('KRSNTD0001','KRSNTD0003') AND TRIM(D.KEY_10) IS NULL AND D.TARGET = A.BUYER AND D.KEY_1 = A.QUOTATION_NO AND D.KEY_2 = A.QUOTATION_SEQ AND D.KEY_3 = A.REVISION AND A.BUYER = B.BUYER AND A.QUOTATION_NO = B.QUOTATION_NO AND A.QUOTATION_SEQ= B.QUOTATION_SEQ AND A.REVISION = B.REVISION AND B.STATUS = 'C' AND B.AGENT = C.COM_CODE(+) AND B.BID_SUCCESS_FLAG = 'Y' AND D.TARGET = '$G_RS.BUYER$' AND D.KEY_1 = '$G_RS.QUOTATION_NO$' AND D.KEY_2 = '$G_RS.QUOTATION_SEQ$' AND D.KEY_3 = '$G_RS.REVISION$'
DECLARE
V_SEND_DATE KEPRQDT.SEND_DATE%TYPE; V_SEND_TIME KEPRQDT.SEND_TIME%TYPE; V_SEND_DATETIME ICOMTRXL.KEY_8%TYPE;
BEGIN
SELECT TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') INTO V_SEND_DATE, V_SEND_TIME, V_SEND_DATETIME FROM DUAL;
UPDATE ICOMTRXL SET KEY_10 = 'X', KEY_9 = TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') WHERE DOC_NAME = 'QTHDDOWN' AND TARGET = '$G_RS.BUYER$' AND KEY_1 = '$G_RS.QUOTATION_NO$' AND KEY_2 = '$G_RS.QUOTATION_SEQ$' AND KEY_3 = '$G_RS.REVISION$' AND TRIM(KEY_10) IS NULL ;
UPDATE KEPRQDT SET SEND_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), SEND_TIME = TO_CHAR(SYSDATE,'HH24MISS') WHERE BUYER = '$G_RS.BUYER$' AND QUOTATION_NO = '$G_RS.QUOTATION_NO$' AND QUOTATION_SEQ= '$G_RS.QUOTATION_SEQ$' AND REVISION = '$G_RS.REVISION$' ;
END;
UPDATE ICOMTRXL SET KEY_10 = 'E', KEY_9 = TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') WHERE DOC_NAME = 'QTHDDOWN' AND TARGET = '$G_RS.BUYER$' AND KEY_1 = '$G_RS.QUOTATION_NO$' AND KEY_2 = '$G_RS.QUOTATION_SEQ$' AND KEY_3 = '$G_RS.REVISION$' AND TRIM(KEY_10) IS NULL
